    "ingestedAt": "03/11/2026 às 21:43",
    "imageUrl": "https://imagens.ebc.com.br/0TannUBoqWXvyBKGuoKEpgSJ8qw=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/img_3665.jpg?itok=syRHATjw",
